import pytest
from qutebrowser.qt.network import QSslError

from qutebrowser.browser.webkit import certificateerror
from qutebrowser.utils import usertypes


class FakeError:

    def __init__(self, msg):
        self.msg = msg

    def errorString(self):
        return self.msg


@pytest.mark.parametrize('errors, expected', [
    (
        [QSslError(QSslError.SslError.UnableToGetIssuerCertificate)],
        ['<p>The issuer certificate could not be found</p>'],
    ),
    (
        [
            QSslError(QSslError.SslError.UnableToGetIssuerCertificate),
            QSslError(QSslError.SslError.UnableToDecryptCertificateSignature),
        ],
        [
            '<ul>',
            '<li>The issuer certificate could not be found</li>',
            '<li>The certificate signature could not be decrypted</li>',
            '</ul>',
        ],
    ),

    (
        [FakeError('Escaping test: <>&"\'')],
        ['<p>Escaping test: &lt;&gt;&amp;&quot;&#x27;</p>'],
    ),
    (
        [
            FakeError('Escaping test 1: <>&"\''),
            FakeError('Escaping test 2: <>&"\''),
        ],
        [
            '<ul>',
            '<li>Escaping test 1: &lt;&gt;&amp;&quot;&#x27;</li>',
            '<li>Escaping test 2: &lt;&gt;&amp;&quot;&#x27;</li>',
            '</ul>',
        ],
    ),
])
def test_html(errors, expected):
    wrapper = certificateerror.CertificateErrorWrapper(errors)
    lines = [line.strip() for line in wrapper.html().splitlines() if line.strip()]
    assert lines == expected


class FakeReply:

    def __init__(self):
        self.ignore_calls = 0

    def ignoreSslErrors(self):
        self.ignore_calls += 1


def test_reply_decision():
    reply = FakeReply()
    wrapper = certificateerror.CertificateErrorWrapper(
        reply=reply, errors=[FakeError('test')])

    assert reply.ignore_calls == 0
    assert not wrapper.certificate_was_accepted()

    wrapper.accept_certificate()
    assert reply.ignore_calls == 1
    assert wrapper.certificate_was_accepted()

    wrapper.reject_certificate()
    assert reply.ignore_calls == 1
    assert not wrapper.certificate_was_accepted()

    with pytest.raises(usertypes.UndeferrableError):
        wrapper.defer()


def test_positional_reply():
    reply = FakeReply()
    wrapper = certificateerror.CertificateErrorWrapper(
        reply, [FakeError('test')])
    wrapper.accept_certificate()
    assert reply.ignore_calls == 1
