from typing import Optional, Sequence, cast

from qutebrowser.qt.network import QNetworkReply, QSslError

from qutebrowser.utils import usertypes, utils, debug


class CertificateErrorWrapper(usertypes.AbstractCertificateErrorWrapper):

    """A wrapper over a list of QSslErrors."""

    def __init__(
            self,
            reply: Optional[QNetworkReply] = None,
            errors: Optional[Sequence[QSslError]] = None,
    ) -> None:
        super().__init__()
        # Keep the old single-positional-argument form for existing callers.
        if errors is None:
            errors = cast(Sequence[QSslError], reply)
            reply = None
        self._reply = reply
        self._errors = tuple(errors)  # needs to be hashable

    def __str__(self) -> str:
        return '\n'.join(err.errorString() for err in self._errors)

    def __repr__(self) -> str:
        return utils.get_repr(
            self,
            errors=[debug.qenum_key(QSslError, err.error()) for err in self._errors],
            string=str(self))

    def __hash__(self) -> int:
        return hash(self._errors)

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, CertificateErrorWrapper):
            return NotImplemented
        return self._errors == other._errors

    def is_overridable(self) -> bool:
        return True

    def accept_certificate(self) -> None:
        super().accept_certificate()
        if self._reply is not None:
            self._reply.ignoreSslErrors()

    def reject_certificate(self) -> None:
        super().reject_certificate()

    def defer(self) -> None:
        raise usertypes.UndeferrableError

    def html(self) -> str:
        if len(self._errors) <= 1:
            return super().html()

        items = '\n'.join(
            f'<li>{html.escape(err.errorString())}</li>'
            for err in self._errors)
        return f'<ul>\n{items}\n</ul>'

